int16_t signed16(int64_t n){const auto u=uint16_t(n);return int16_t(int(u)-(u>32767?65536:0));}
int32_t wrap32(int64_t n){uint32_t u=uint32_t(n);return int32_t(int64_t(u)-(u>0x7fffffffU?0x100000000LL:0));}
