float fbits(uint32_t bits){float v;std::memcpy(&v,&bits,4);return v;}
std::vector<uint8_t> hex(const V& chunks,size_t n){need(chunks.is_array(),"Noritsu: missing hex chunks");std::vector<uint8_t> out;out.reserve(n);auto digit=[](char c){if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;if(c>='A'&&c<='F')return c-'A'+10;throw std::invalid_argument("Noritsu: invalid hexadecimal data");};for(auto& p:chunks.array){need(p->is_string()&&p->str.size()%2==0,"Noritsu: malformed hex chunk");for(size_t i=0;i<p->str.size();i+=2){need(out.size()<n,"Noritsu: oversized binary table");out.push_back(uint8_t(digit(p->str[i])*16+digit(p->str[i+1])));}}need(out.size()==n,"Noritsu: truncated binary table");return out;}
